from src.tools.t01v2_live_progress import read_prefix,archive
from src.tools.t01_partition import ROOT
NAME='diag_pilot709803_training_0626_01'
assert os.environ.get('CVPR_RUN_NAME')==NAME
def expired(*_):raise TimeoutError('12s pilot original metadata/journal snapshot')
signal.signal(signal.SIGALRM,expired);signal.alarm(12)
out=ROOT/'logs/review'/NAME;out.mkdir(parents=True,exist_ok=False);evidence=out/'evidence';evidence.mkdir()
