 if p.is_file():
  b=p.read_bytes();assert len(b)<32*1024*1024;d=json.loads(b);r.update(reference=archive(b,evidence,stem+'_result.json'),meta=d.get('_meta'),original_metrics=d.get('metrics'))
 log=ROOT/'logs/runs'/(stem+'.log');r['log_exists']=log.is_file()
