   b,extent=read_prefix(p,limit=2*1024*1024);r['extent']=extent;r['original_prefix']=archive(b,evidence,p.name);r['original_stage_records']=[row for row in (json.loads(line) for line in b.splitlines() if line.strip()) if row.get('record_kind') in ('pilot_holdout_complete','pilot_update_begin','actual_actor_consistency_update','pilot_update_complete','pilot_update_failed')]
 record['training_artifacts'].append(r)
p=out/'snapshot.json'
with p.open('x') as f:json.dump(record,f,sort_keys=True,indent=2)
brief={'report':{'file':str(p.relative_to(ROOT)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()},'observed_at_utc':record['observed_at_utc'],'results':[],'training_artifacts':record['training_artifacts']}
for r in record['results']:
 brief['results'].append({**{k:r[k] for k in ('file','exists','reference') if k in r},'meta':{k:r.get('meta',{}).get(k) for k in ('start','end','exit_code')},'metrics':{k:r.get('original_metrics',{}).get(k) for k in ('kind','producer_exit_code','engineering_smoke_completed','pilot_completed','actual_completed_updates','errors','cleanup_errors','checkpoint_saved','source_authentication_seconds','model_initialization_seconds')},'original_log_tail':r.get('original_log_tail','')[-5000:]})
print('ORIGINAL_PILOT_TRAINING_SNAPSHOT: '+json.dumps(brief,sort_keys=True),flush=True);signal.alarm(0)

